akturaer</span><strong>{{$invoices->where('status','unpaid')->count()}}</strong></a><a class="tile" href="#tickets"><i>◫</i><span>Åbne tickets</span><strong>{{$tickets->where('status','!=','closed')->count()}}</strong></a><a class="tile" href="/store"><i>＋</i><span>Produkter</span><strong>{{$products->count()}}</strong></a></div><div class="contentgrid"><div><section class="card" id="services"><div class="cardtitle"><span>Mine tjenester</span><small>{{$services->count()+$vpsServices->count()}} registrerede</small></div>@foreach($services as $s)<a class="item" href="/"><div><strong>{{$s->name??('Game Server #'.$s->id)}}</strong><div class="meta">Game Server · Service #{{$s->id}}</div></div><div class="right"><span class="status">Aktiv</span><span class="btn secondary">Administrér</span></div></a>@endforeach @foreach($vpsServices as $v)<a class="item" href="/client/vps/{{$v->id}}"><div><strong>{{$v->hostname?:('VPS #'.$v->id)}}</strong><div class="meta">VPS · {{$v->ip_address?:'IP afventer'}} · #{{$v->id}}</div></div><div class="right"><span class="status {{$v->status==='awaiting_payment'?'wait':''}}">{{str_replace('_',' ',$v->status)}}</span><span class="btn secondary">Administrér</span></div></a>@endforeach @if($services->isEmpty()&&$vpsServices->isEmpty())<div class="empty">Du har endnu ingen tjenester.<br><br><a class="btn" href="/store">Bestil din første tjeneste</a></div>@endif</section><section class="card" id="tickets"><div class="cardtitle"><span>Seneste support tickets</span><a class="btn" href="#new-ticket">Opret ticket</a></div>@forelse($tickets->take(5) as $t)<a class="item" href="/client/tickets/{{$t->id}}"><div><strong>#{{$t->id}} · {{$t->subject}}</strong><div class="meta">{{ucfirst($t->department??'support')}} · {{$t->updated_at}}</div></div><span class="status {{$t->status==='closed'?'closed':'wait'}}">{{str_replace('_',' ',$t->status)}}</span></a>@empty<div class="empty">Ingen support tickets.</div>@endforelse</section></div><aside><section class="card"><div class="cardtitle">Hurtige genveje</div><div class="quick"><a href="/store/games"><b>▣</b>Bestil game server</a><a href="/store/vps"><b>◇</b>Bestil VPS</a><a href="/client/invoices"><b>▤</b>Se fakturaer</a><a href="#new-ticket"><b>?</b>Kontakt support</a></div></section><section class="card"><div class="cardtitle"><span>Seneste fakturaer</span><a href="/client/invoices" style="font-size:9px;color:#77aaff">Se alle</a></div>@forelse($invoices->take(5) as $i)<a class="item" href="/client/invoices/{{$i->id}}"><div><strong>{{$i->number??('Faktura #'.$i->id)}}</strong><div class="meta">{{ucfirst($i->status)}}</div></div><div class="price"><strong>{{number_format((float)($i->total??0),2,',','.')}} {{$i->currency??'DKK'}}</strong><span class="status {{$i->status==='paid'?'':'wait'}}">{{$i->status}}</span></div></a>@empty<div class="empty">Ingen fakturaer.</div>@endforelse</section><section class="card" id="new-ticket"><div class="cardtitle">Åbn en support ticket</div><form method="POST" action="/client/tickets" class="body">@csrf<input class="field" name="subject" required placeholder="Emne"><select class="field" name="department"><option value="support">Support</option><option value="billing">Fakturering</option><option value="sales">Salg</option></select><select class="field" name="priority"><option value="low">Lav prioritet</option><option value="normal" selected>Normal prioritet</option><option value="high">Høj prioritet</option></select><textarea class="field" name="message" required rows="5" placeholder="Hvordan kan vi hjælpe dig?"></textarea><button class="btn">Send ticket</button></form></section></aside></div></section></div></main><footer class="footer">Nodexa · Hosting Cloud · 2026</footer></body></html>